        emon.Testport.assertEq(emon.Port.cellsLen(d.b), 0, "b is empty");
        emon.Testport.assertEq(emon.Port.bufLen(d.png), 0, "png is empty");
        emon.Testport.assertEq(emon.Port.bufLen(d.spare), 0, "spare is empty");
        emon.Testport.assertEq(d.n, 0, "n is zero");
        emon.Testport.assertText(d.out, "", "out is empty");
